-- GG3 · Unit 0 «Get started!» · Test
-- Собрано скриптом builds/gg3/u0/build.py. Не заливать, пока не назовут,
-- куда переехала платформа. Проверка:
--   python3.13 tools/val.py builds/gg3/u0 gg3/u0

do $$
declare
  v_course uuid;
  v_unit   uuid;
  v_lesson uuid;
  v_media  text := 'https://classroom.wowteach.ru/media/';
begin
  select id into v_course from classroom_courses where slug = 'gg3';
  if v_course is null then raise exception 'курс gg3 не найден'; end if;

  select id into v_unit from classroom_units where course_id = v_course and sort_order = 0;
  if v_unit is null then
    insert into classroom_units (course_id, title, sort_order)
    values (v_course, 'Unit 0', 0)
    returning id into v_unit;
  end if;

  select id into v_lesson from classroom_lessons
   where unit_id = v_unit and sort_order = 0;
  if v_lesson is null then
    insert into classroom_lessons (unit_id, title, kind, sort_order, pass_threshold, is_published)
    values (v_unit, 'Unit 0 Test', 'test', 0, 90, false)
    returning id into v_lesson;
  else
    update classroom_lessons
       set title = 'Unit 0 Test', kind = 'test', pass_threshold = 90
     where id = v_lesson;
  end if;

  insert into classroom_blocks (lesson_id, type, payload, sort_order) values
    (v_lesson, 'text', replace($blk${"html": "<p>Сегодня у нас с тобой тест по нулевому юниту Get started! Проверим Present Simple, be going to, вопросы, еду и всё, что мы повторяли. Уверена, ты справишься!</p>"}$blk$, '@@MEDIA@@', v_media)::jsonb, 0),
    (v_lesson, 'match', replace($blk${"title": "Match the place with what you can do there.", "pairs": [{"left": "You can see paintings here.", "right": "museum", "right_audio": "", "right_audio_tts": "museum"}, {"left": "You can watch a film here.", "right": "cinema", "right_audio": "", "right_audio_tts": "cinema"}, {"left": "You can stay here on holiday.", "right": "hotel", "right_audio": "", "right_audio_tts": "hotel"}, {"left": "You can watch a football match here.", "right": "stadium", "right_audio": "", "right_audio_tts": "stadium"}, {"left": "You can have dinner here.", "right": "restaurant", "right_audio": "", "right_audio_tts": "restaurant"}, {"left": "A doctor works here.", "right": "hospital", "right_audio": "", "right_audio_tts": "hospital"}], "needs_review": false}$blk$, '@@MEDIA@@', v_media)::jsonb, 1),
    (v_lesson, 'quiz', replace($blk${"title": "Means of transport and places — choose the right word.", "questions": [{"q": "Harry goes to school ___ bike.", "type": "single", "correct": [0], "options": [{"text": "by"}, {"text": "on"}, {"text": "with"}]}, {"q": "It goes under the ground. It’s the ___.", "type": "single", "correct": [0], "options": [{"text": "underground"}, {"text": "tram"}, {"text": "boat"}]}, {"q": "Emma and Gran travel to France ___ plane.", "type": "single", "correct": [0], "options": [{"text": "by"}, {"text": "in"}, {"text": "at"}]}, {"q": "George and his dad go to the ___ to watch the football.", "type": "single", "correct": [0], "options": [{"text": "stadium"}, {"text": "museum"}, {"text": "bank"}]}, {"q": "You can take money out at the ___.", "type": "single", "correct": [0], "options": [{"text": "bank"}, {"text": "park"}, {"text": "theatre"}]}], "needs_review": false}$blk$, '@@MEDIA@@', v_media)::jsonb, 2),
    (v_lesson, 'quiz', replace($blk${"title": "Present Simple and adverbs of frequency — choose the right option.", "questions": [{"q": "George ___ karate on Tuesdays.", "type": "single", "correct": [0], "options": [{"text": "does"}, {"text": "do"}, {"text": "doing"}]}, {"q": "Emma ___ have dance classes on Mondays.", "type": "single", "correct": [0], "options": [{"text": "doesn’t"}, {"text": "don’t"}, {"text": "isn’t"}]}, {"q": "___ Harry play tennis on Thursdays?", "type": "single", "correct": [0], "options": [{"text": "Does"}, {"text": "Do"}, {"text": "Is"}]}, {"q": "I ___ late for school.", "type": "single", "correct": [0], "options": [{"text": "am never"}, {"text": "never am"}, {"text": "never"}]}, {"q": "She ___ to school by bike.", "type": "single", "correct": [0], "options": [{"text": "always goes"}, {"text": "goes always"}, {"text": "always go"}]}], "needs_review": false}$blk$, '@@MEDIA@@', v_media)::jsonb, 3),
    (v_lesson, 'quiz', replace($blk${"title": "Question words — complete the questions about Harry’s dad.", "questions": [{"q": "___ does your dad do?", "type": "single", "correct": [0], "options": [{"text": "What"}, {"text": "Who"}, {"text": "When"}]}, {"q": "___ does he work?", "type": "single", "correct": [0], "options": [{"text": "Where"}, {"text": "How"}, {"text": "What"}]}, {"q": "___ does he start work?", "type": "single", "correct": [0], "options": [{"text": "When"}, {"text": "Where"}, {"text": "Who"}]}, {"q": "___ does he travel to work?", "type": "single", "correct": [0], "options": [{"text": "How"}, {"text": "What"}, {"text": "When"}]}], "needs_review": false}$blk$, '@@MEDIA@@', v_media)::jsonb, 4),
    (v_lesson, 'quiz', replace($blk${"title": "Jobs — who is it?", "questions": [{"q": "This person looks after animals when they are ill.", "type": "single", "correct": [0], "options": [{"text": "a vet"}, {"text": "a farmer"}, {"text": "a nurse"}]}, {"q": "This person cooks in a restaurant.", "type": "single", "correct": [0], "options": [{"text": "a chef"}, {"text": "a waiter"}, {"text": "a shop assistant"}]}, {"q": "This person helps people in hospital and works with a doctor.", "type": "single", "correct": [0], "options": [{"text": "a nurse"}, {"text": "a teacher"}, {"text": "a pilot"}]}, {"q": "This person flies a plane.", "type": "single", "correct": [0], "options": [{"text": "a pilot"}, {"text": "a bus driver"}, {"text": "a builder"}]}], "needs_review": false}$blk$, '@@MEDIA@@', v_media)::jsonb, 5),
    (v_lesson, 'quiz', replace($blk${"title": "be going to — choose the right option.", "questions": [{"q": "I ___ study Geography more this year.", "type": "single", "correct": [0], "options": [{"text": "am going to"}, {"text": "going to"}, {"text": "am going"}]}, {"q": "My parents ___ buy me a laptop.", "type": "single", "correct": [0], "options": [{"text": "are going to"}, {"text": "is going to"}, {"text": "going to"}]}, {"q": "___ you going to have lunch at school?", "type": "single", "correct": [0], "options": [{"text": "Are"}, {"text": "Do"}, {"text": "Is"}]}, {"q": "He ___ going to get up late again.", "type": "single", "correct": [0], "options": [{"text": "isn’t"}, {"text": "aren’t"}, {"text": "doesn’t"}]}], "needs_review": false}$blk$, '@@MEDIA@@', v_media)::jsonb, 6),
    (v_lesson, 'quiz', replace($blk${"title": "Adjectives with prepositions — choose the right word.", "questions": [{"q": "I’m bad ___ cooking.", "type": "single", "correct": [0], "options": [{"text": "at"}, {"text": "in"}, {"text": "of"}]}, {"q": "She’s interested ___ science.", "type": "single", "correct": [0], "options": [{"text": "in"}, {"text": "at"}, {"text": "about"}]}, {"q": "He’s scared ___ spiders.", "type": "single", "correct": [0], "options": [{"text": "of"}, {"text": "at"}, {"text": "for"}]}, {"q": "They’re excited ___ the new game.", "type": "single", "correct": [0], "options": [{"text": "about"}, {"text": "of"}, {"text": "in"}]}], "needs_review": false}$blk$, '@@MEDIA@@', v_media)::jsonb, 7),
    (v_lesson, 'quiz', replace($blk${"title": "Food and drink — some, any, how much, how many.", "questions": [{"q": "There ___ some apples in the kitchen.", "type": "single", "correct": [0], "options": [{"text": "are"}, {"text": "is"}, {"text": "be"}]}, {"q": "There isn’t ___ sugar in my tea.", "type": "single", "correct": [0], "options": [{"text": "any"}, {"text": "some"}, {"text": "a"}]}, {"q": "___ milk is there?", "type": "single", "correct": [0], "options": [{"text": "How much"}, {"text": "How many"}, {"text": "How long"}]}, {"q": "___ eggs are there?", "type": "single", "correct": [0], "options": [{"text": "How many"}, {"text": "How much"}, {"text": "How often"}]}, {"q": "Have we got ___ bread?", "type": "single", "correct": [0], "options": [{"text": "any"}, {"text": "many"}, {"text": "a"}]}], "needs_review": false}$blk$, '@@MEDIA@@', v_media)::jsonb, 8),
    (v_lesson, 'order', replace($blk${"words": ["She", "doesn’t go", "to the gym", "on Mondays."], "sentence": "She doesn’t go to the gym on Mondays.", "audio": "", "audio_tts": "She doesn’t go to the gym on Mondays."}$blk$, '@@MEDIA@@', v_media)::jsonb, 9),
    (v_lesson, 'order', replace($blk${"words": ["How often", "do you", "travel", "by train?"], "sentence": "How often do you travel by train?", "audio": "", "audio_tts": "How often do you travel by train?"}$blk$, '@@MEDIA@@', v_media)::jsonb, 10),
    (v_lesson, 'order', replace($blk${"words": ["I’m", "going to", "study", "English", "this year."], "sentence": "I’m going to study English this year.", "audio": "", "audio_tts": "I’m going to study English this year."}$blk$, '@@MEDIA@@', v_media)::jsonb, 11),
    (v_lesson, 'order', replace($blk${"words": ["There", "isn’t", "any juice", "in the fridge."], "sentence": "There isn’t any juice in the fridge.", "audio": "", "audio_tts": "There isn’t any juice in the fridge."}$blk$, '@@MEDIA@@', v_media)::jsonb, 12),
    (v_lesson, 'exact_input', replace($blk${"title": "Containers — write the missing word.", "items": [{"prompt": "1. a ___ of chocolate", "accept": ["bar", "Bar"]}, {"prompt": "2. a ___ of water", "accept": ["bottle", "Bottle"]}, {"prompt": "3. a ___ of tuna", "accept": ["can", "Can"]}, {"prompt": "4. a ___ of milk", "accept": ["carton", "Carton"]}, {"prompt": "5. a ___ of flour", "accept": ["packet", "Packet"]}], "needs_review": false}$blk$, '@@MEDIA@@', v_media)::jsonb, 13),
    (v_lesson, 'text', replace($blk${"html": "<p><b>READING.</b> Прочитай текст и ответь, верно или неверно.</p><p>The Nichols family live in London. Peter is George and Harry’s dad. He is a doctor and he works at Park Hill General Hospital. He usually starts work at eight o’clock and he travels to work by motorbike. Angela, their mum, is a teacher. She often takes the bus to school. Harry is thirteen. He is good at tennis and he is interested in art. George doesn’t like sport, but he is excited about his new computer. At the weekend the family always go to the park.</p>"}$blk$, '@@MEDIA@@', v_media)::jsonb, 14),
    (v_lesson, 'truefalse', replace($blk${"title": "True or false?", "statements": [{"text": "Peter works at a hospital.", "correct": true}, {"text": "Peter travels to work by bus.", "correct": false}, {"text": "Angela is a doctor.", "correct": false}, {"text": "Harry is interested in art.", "correct": true}, {"text": "The family never go to the park.", "correct": false}]}$blk$, '@@MEDIA@@', v_media)::jsonb, 15),
    (v_lesson, 'text', replace($blk${"html": "<p><b>LISTENING 🎧</b> Послушай рассказ про Эмму. Текста не будет — слушай и отвечай на вопросы ниже. Можно послушать два раза.</p>", "audio": ""}$blk$, '@@MEDIA@@', v_media)::jsonb, 16),
    (v_lesson, 'quiz', replace($blk${"title": "Послушай ещё раз и выбери правильный ответ.", "questions": [{"q": "How old is Emma?", "type": "single", "correct": [0], "options": [{"text": "thirteen"}, {"text": "nine"}, {"text": "thirty"}]}, {"q": "How does Emma usually go to school?", "type": "single", "correct": [0], "options": [{"text": "by bike"}, {"text": "by car"}, {"text": "by bus"}]}, {"q": "How often has she got dance classes?", "type": "single", "correct": [0], "options": [{"text": "twice a week"}, {"text": "every day"}, {"text": "at the weekend"}]}, {"q": "What is she going to study more this year?", "type": "single", "correct": [0], "options": [{"text": "Geography"}, {"text": "Maths"}, {"text": "Art"}]}, {"q": "What is Emma scared of?", "type": "single", "correct": [0], "options": [{"text": "spiders"}, {"text": "dogs"}, {"text": "the dark"}]}], "needs_review": false}$blk$, '@@MEDIA@@', v_media)::jsonb, 17),
    (v_lesson, 'exact_input', replace($blk${"title": "DICTATION ✍️ Послушай предложение и запиши его целиком.", "needs_review": false, "items": [{"audio": "", "audio_tts": "Harry usually plays tennis on Thursdays.", "prompt": "1.", "accept": ["Harry usually plays tennis on Thursdays.", "Harry usually plays tennis on Thursdays"]}, {"audio": "", "audio_tts": "My dad travels to work by motorbike.", "prompt": "2.", "accept": ["My dad travels to work by motorbike.", "My dad travels to work by motorbike"]}, {"audio": "", "audio_tts": "There isn’t any milk in the fridge.", "prompt": "3.", "accept": ["There isn’t any milk in the fridge.", "There isn’t any milk in the fridge", "There isn't any milk in the fridge.", "There isn't any milk in the fridge"]}, {"audio": "", "audio_tts": "We are going to visit a museum.", "prompt": "4.", "accept": ["We are going to visit a museum.", "We are going to visit a museum"]}]}$blk$, '@@MEDIA@@', v_media)::jsonb, 18),
    (v_lesson, 'speaking', replace($blk${"title": "SPEAKING TASK 🎤", "needs_review": true, "html": "<p>Ответь на вопросы, 6–8 предложений. Нажми на микрофон и запиши ответ.</p><ol><li>What do you usually do at the weekend?</li><li>How do you travel to school?</li><li>What are you good at? What are you scared of?</li><li>What are you going to do this year?</li><li>What is there in your fridge at home?</li></ol>"}$blk$, '@@MEDIA@@', v_media)::jsonb, 19),
    (v_lesson, 'text', replace($blk${"html": "<p>Ты справился! 🌟 Это был тест за весь нулевой юнит: город и транспорт, профессии, школа, характер и еда.</p>"}$blk$, '@@MEDIA@@', v_media)::jsonb, 20)
  on conflict (lesson_id, sort_order) do update
    set type = excluded.type, payload = excluded.payload;

  raise notice 'GG3 Unit 0 Test: % блоков', 21;
end $$;
